// Track an insult streak and a binary mood: gifts clear the streak, an apology warms only if the streak is under 2, and a second consecutive insult makes Robin cold.
function visible(actions) {
  let mood = "cold";
  let streak = 0;
  for (const action of actions) {
    if (action === "insult") {
      streak += 1;
      if (streak >= 2) mood = "cold";
    } else if (action === "apologise") {
      if (streak < 2) {
        mood = "warm";
      } else {
        mood = "cold";
      }
      streak = 0;
    } else if (action === "gift") {
      streak = 0;
    }
  }
  return { mood: mood };
}

